def calculate_E(a, b, c):
    """Calculates the expression E."""
    S = a + b + c
    P = a*b + b*c + c*a
    numerator = S * P + S
    denominator = 4 * a * b * c

    if denominator == 0:
        return None # Should not happen for positive integers

    return numerator / denominator

results = {}

# Search for distinct positive integers a, b, c such that a + b + c <= 10
# We enforce a < b < c due to symmetry.

for a in range(1, 8): # Max possible a if a+b+c <= 10 and a < b < c (1+2+3=6, 2+3+5=10, 1+2+7=10, 1+3+6=10, 1+4+5=10)
    for b in range(a + 1, 8):
        for c in range(b + 1, 11):
            if a + b + c > 10:
                break

            E = calculate_E(a, b, c)

            # We only care if E is an integer
            if E == int(E):
                n = int(E)
                triple = (a, b, c)

                # Store the result: (n, triple)
                if n not in results:
                    results[n] = []

                # Store the sorted triple representation
                results[n].append(tuple(sorted(triple)))

print("--- Integer Values of E Found ---")
for n, triples in results.items():
    print(f"n = {n}: Triples found: {triples}")

print("\n--- Summary ---")
print(f"Unique integer values of n found: {sorted(results.keys())}")
